// The shell runtime (packages/render-html/src/shell-runtime.js) is authored as a plain file so it can be read, linted and hashed.
// This writes the TypeScript module the library imports (a string constant and its hash, so the browser playground can bundle it
// and `tsc` carries it into dist/) and the hex digest a reviewer checks with `sha256sum`. `--check` writes nothing and fails when
// a generated file is out of date or the runtime breaks a gate: that is the 8 KiB build gate (internal spec, lede-lang/meta).
//   node scripts/gen-runtime.ts [--check]
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const dir = join(import.meta.dirname, '..', 'packages', 'render-html', 'src');
const LIMIT = 8192;
const src = readFileSync(join(dir, 'shell-runtime.js'), 'utf8');

const problems: string[] = [];
if (Buffer.byteLength(src) > LIMIT) problems.push(`the runtime is ${Buffer.byteLength(src)} bytes; the limit is ${LIMIT}`);
if (/[^\n -~]/.test(src)) problems.push('the runtime has a byte outside printable ASCII and LF (a CR, a tab or a non-ASCII character)');
for (const bad of ['</script', '<script', '<!--']) if (src.includes(bad)) problems.push(`the runtime contains ${bad}`);
if (problems.length) {
  process.stderr.write(`gen-runtime: ${problems.join('; ')}\n`);
  process.exit(1);
}

const digest = createHash('sha256').update(src, 'utf8').digest();
const check = process.argv.includes('--check');
const outputs: [string, string][] = [
  [
    'shell-runtime.ts',
    `// Generated by scripts/gen-runtime.ts from shell-runtime.js; do not edit. The text is what the page inlines, and the hash is its policy value.\n` +
      `export const RUNTIME: string = ${JSON.stringify(src)};\n` +
      `export const RUNTIME_SHA256: string = 'sha256-${digest.toString('base64')}';\n`,
  ],
  ['shell-runtime.sha256', `${digest.toString('hex')}\n`],
];

let stale = false;
for (const [name, text] of outputs) {
  const path = join(dir, name);
  if (check) {
    let have = '';
    try {
      have = readFileSync(path, 'utf8');
    } catch {
      // missing counts as stale
    }
    if (have !== text) {
      process.stderr.write(`gen-runtime: ${name} is out of date; run node scripts/gen-runtime.ts\n`);
      stale = true;
    }
  } else writeFileSync(path, text);
}
process.exit(stale ? 1 : 0);
